/*
 * dotclaude catalog site. One script for every page.
 *
 * Shared: theme toggle, mobile menu, copy buttons.
 * Catalog (home) only: fetches data.json (generated by `pnpm gen`), keeps the
 * filters in the query string so any view is a shareable link, ranks search
 * results, and renders with plain DOM APIs. No build step, no dependencies.
 *
 * Query grammar on the home page:  /?q=term&type=skill&category=academic&plugin=thesis&sort=name
 * Old hash links (#/plugins, #/install, #/<type>/<name>, #/?q=...) redirect
 * to their page or query so nothing bookmarked before the rebuild breaks.
 */

const DATA_URL = "data.json";
const $ = (id) => document.getElementById(id);

/* Shared ------------------------------------------------------------------- */

function initTheme() {
  const button = document.querySelector(".theme-toggle");
  if (!button) return;
  const sun = button.querySelector(".icon-sun");
  const moon = button.querySelector(".icon-moon");
  const media = window.matchMedia("(prefers-color-scheme: dark)");

  const current = () =>
    document.documentElement.dataset.theme || (media.matches ? "dark" : "light");
  const paint = () => {
    const dark = current() === "dark";
    sun.hidden = dark;
    moon.hidden = !dark;
    button.setAttribute("aria-label", dark ? "Switch to light theme" : "Switch to dark theme");
  };
  button.addEventListener("click", () => {
    const next = current() === "dark" ? "light" : "dark";
    document.documentElement.dataset.theme = next;
    try {
      localStorage.setItem("theme", next);
    } catch {
      // Private mode or storage disabled: the choice lasts for this page only.
    }
    paint();
  });
  media.addEventListener("change", paint);
  paint();
}

function initMenu() {
  const toggle = document.querySelector(".menu-toggle");
  const nav = $("site-nav");
  if (!toggle || !nav) return;
  const set = (open) => {
    toggle.setAttribute("aria-expanded", String(open));
    if (open) nav.dataset.open = "";
    else delete nav.dataset.open;
  };
  toggle.addEventListener("click", () => set(toggle.getAttribute("aria-expanded") !== "true"));
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && toggle.getAttribute("aria-expanded") === "true") {
      set(false);
      toggle.focus();
    }
  });
  document.addEventListener("click", (e) => {
    if (!nav.contains(e.target) && !toggle.contains(e.target)) set(false);
  });
}

async function copy(text, button) {
  try {
    await navigator.clipboard.writeText(text);
    button.dataset.done = "";
    button.textContent = "Copied";
    setTimeout(() => {
      delete button.dataset.done;
      button.textContent = "Copy";
    }, 1500);
  } catch {
    // Clipboard is unavailable (insecure context, denied permission); select
    // the command so one keystroke copies it.
    button.textContent = "Select";
    const code = button.parentElement.querySelector("code");
    const range = document.createRange();
    range.selectNodeContents(code);
    const selection = window.getSelection();
    selection.removeAllRanges();
    selection.addRange(range);
  }
}

function initCopy() {
  document.addEventListener("click", (e) => {
    const button = e.target.closest(".copy");
    if (!button) return;
    const block = button.closest("[data-copy]");
    if (block) copy(block.dataset.copy, button);
  });
}

/* Catalog state ---------------------------------------------------------------- */

const state = {
  data: null,
  q: "",
  type: "",
  category: "",
  plugin: "",
  sort: "category",
};

const els = {};

function readQuery() {
  const params = new URLSearchParams(location.search);
  state.q = (params.get("q") ?? "").trim();
  state.type = params.get("type") ?? "";
  state.category = params.get("category") ?? "";
  state.plugin = params.get("plugin") ?? "";
  const sort = params.get("sort") ?? "category";
  state.sort = ["category", "name", "type"].includes(sort) ? sort : "category";
}

function buildQuery(overrides = {}) {
  const next = { ...state, ...overrides };
  const params = new URLSearchParams();
  if (next.q) params.set("q", next.q);
  if (next.type) params.set("type", next.type);
  if (next.category) params.set("category", next.category);
  if (next.plugin) params.set("plugin", next.plugin);
  if (next.sort && next.sort !== "category") params.set("sort", next.sort);
  const query = params.toString();
  return `${location.pathname}${query ? `?${query}` : ""}`;
}

function navigate(overrides, { replace = false } = {}) {
  const url = buildQuery(overrides);
  if (url === `${location.pathname}${location.search}`) return;
  history[replace ? "replaceState" : "pushState"](null, "", url);
  readQuery();
  render();
}

/**
 * Links from before the rebuild kept state in the hash. Send each to its
 * page or query so bookmarks and search results still land somewhere real.
 */
function redirectLegacyHash() {
  if (!location.hash.startsWith("#/")) return false;
  const raw = location.hash.slice(2);
  const [path, query = ""] = raw.split("?");
  if (path === "plugins" || path === "install") {
    location.replace(`/${path}/`);
    return true;
  }
  if (path.includes("/")) {
    location.replace(`/${path}/`);
    return true;
  }
  location.replace(`${location.pathname}${query ? `?${query}` : ""}`);
  return true;
}

/* Filtering and ranking ----------------------------------------------------- */

const normalize = (s) => s.toLowerCase();
const terms = () => normalize(state.q).split(/\s+/).filter(Boolean);

/** 0 when the item does not match; higher is a better match. */
function score(item, words) {
  if (words.length === 0) return 1;
  const name = normalize(item.name);
  const title = normalize(item.title);
  const desc = normalize(item.description);
  let total = 0;
  for (const word of words) {
    if (name === word) total += 100;
    else if (name.startsWith(word)) total += 60;
    else if (name.includes(word)) total += 40;
    else if (title.includes(word)) total += 25;
    else if (desc.includes(word)) total += 10;
    else if (normalize(item.category).includes(word) || item.plugins.some((p) => p.includes(word)))
      total += 5;
    else return 0;
  }
  return total;
}

function applyFilters(items, { ignore } = {}) {
  const words = terms();
  const out = [];
  for (const item of items) {
    const s = score(item, words);
    if (s === 0) continue;
    if (ignore !== "type" && state.type && item.type !== state.type) continue;
    if (ignore !== "category" && state.category && item.category !== state.category) continue;
    if (ignore !== "plugin" && state.plugin && !item.plugins.includes(state.plugin)) continue;
    out.push({ item, s });
  }
  return out;
}

function countBy(entries, key) {
  const map = new Map();
  for (const { item } of entries) {
    const values = key === "plugins" ? item.plugins : [item[key]];
    for (const v of values) map.set(v, (map.get(v) ?? 0) + 1);
  }
  return map;
}

/* Rendering helpers ------------------------------------------------------------ */

function el(tag, attrs = {}, children = []) {
  const node = document.createElement(tag);
  for (const [key, value] of Object.entries(attrs)) {
    if (value === undefined || value === null || value === false) continue;
    if (key === "text") node.textContent = value;
    else if (key === "class") node.className = value;
    else node.setAttribute(key, value === true ? "" : value);
  }
  for (const child of children) {
    if (child == null) continue;
    node.append(child);
  }
  return node;
}

function escapeRegExp(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

/** Wrap each query term in <mark>, working on text so nothing is injected. */
function highlight(text, words) {
  if (words.length === 0) return [text];
  const pattern = new RegExp(`(${words.map(escapeRegExp).join("|")})`, "ig");
  return text.split(pattern).map((part, i) => (i % 2 === 1 ? el("mark", { text: part }) : part));
}

function titleCase(slug) {
  return slug
    .split("-")
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
    .join(" ");
}

function typeMeta(type) {
  return state.data.types.find((t) => t.type === type);
}

/* Toolbar ------------------------------------------------------------------------ */

function renderToolbar() {
  const { items, types, plugins } = state.data;

  // Each control's counts ignore its own selection, so a number answers
  // "what would I get if I picked this instead" rather than collapsing to 0.
  const byType = countBy(applyFilters(items, { ignore: "type" }), "type");
  const byCategory = countBy(applyFilters(items, { ignore: "category" }), "category");
  const byPlugin = countBy(applyFilters(items, { ignore: "plugins" }), "plugins");
  const allCount = applyFilters(items, { ignore: "type" }).length;

  els.filterType.replaceChildren(
    el("legend", { class: "visually-hidden", text: "Type" }),
    el(
      "button",
      { type: "button", "data-value": "", "aria-pressed": state.type === "" ? "true" : "false" },
      [el("span", { text: "All" }), el("span", { class: "n", text: String(allCount) })],
    ),
    ...types.map((t) =>
      el(
        "button",
        {
          type: "button",
          "data-value": t.type,
          "data-type": t.type,
          "aria-pressed": state.type === t.type ? "true" : "false",
        },
        [
          el("span", { class: "dot", "aria-hidden": "true" }),
          el("span", { text: t.label }),
          el("span", { class: "n", text: String(byType.get(t.type) ?? 0) }),
        ],
      ),
    ),
  );

  const categories = [...new Set(items.map((i) => i.category))].sort();
  fillSelect(
    els.filterCategory,
    "All categories",
    categories.map((c) => [c, `${titleCase(c)} (${byCategory.get(c) ?? 0})`]),
    state.category,
  );
  fillSelect(
    els.filterPlugin,
    "All plugins",
    plugins.map((p) => [p.name, `${p.name} (${byPlugin.get(p.name) ?? 0})`]),
    state.plugin,
  );
  els.sort.value = state.sort;

  const active = Boolean(state.q || state.type || state.category || state.plugin);
  els.clear.hidden = !active;
  els.searchClear.hidden = !state.q;
  els.searchKbd.hidden = Boolean(state.q);
  if (els.search.value !== state.q && document.activeElement !== els.search) {
    els.search.value = state.q;
  }
}

function fillSelect(select, allLabel, options, value) {
  select.replaceChildren(
    el("option", { value: "", text: allLabel }),
    ...options.map(([v, label]) => el("option", { value: v, text: label })),
  );
  select.value = value;
  if (value) select.dataset.active = "";
  else delete select.dataset.active;
}

/* Rows --------------------------------------------------------------------------- */

function row(item, words) {
  return el("li", { class: "row" }, [
    el(
      "a",
      {
        class: "row-link",
        href: `/${item.key}/`,
        "data-key": item.key,
        "data-type": item.type,
      },
      [
        el("span", { class: "dot", "aria-hidden": "true" }),
        el("span", { class: "row-main" }, [
          el("span", { class: "row-head" }, [
            el("code", { class: "row-name" }, highlight(item.name, words)),
            el("span", { class: "row-type", text: item.type }),
            item.title.toLowerCase() !== titleCase(item.name).toLowerCase()
              ? el("span", { class: "row-title" }, highlight(item.title, words))
              : null,
          ]),
          el("span", { class: "row-desc" }, highlight(item.description, words)),
        ]),
        item.plugins.length > 0
          ? el("span", { class: "row-plugins" }, [
              el("span", { class: "visually-hidden", text: "In plugins: " }),
              ...item.plugins.map((p) => el("span", { text: p })),
            ])
          : null,
      ],
    ),
  ]);
}

function groupsFor(entries) {
  const words = terms();
  // Searching ranks by relevance across the whole catalog; grouping would
  // hide the best match under a heading halfway down.
  if (words.length > 0) {
    const sorted = [...entries].sort((a, b) => b.s - a.s || a.item.name.localeCompare(b.item.name));
    return [{ key: "results", label: null, items: sorted.map((e) => e.item) }];
  }
  const items = entries.map((e) => e.item);
  if (state.sort === "name") {
    return [
      {
        key: "all",
        label: null,
        items: [...items].sort((a, b) => a.name.localeCompare(b.name)),
      },
    ];
  }
  if (state.sort === "type") {
    return state.data.types
      .map((t) => ({
        key: t.type,
        label: t.label,
        items: items.filter((i) => i.type === t.type).sort((a, b) => a.name.localeCompare(b.name)),
      }))
      .filter((g) => g.items.length > 0);
  }
  const categories = [...new Set(items.map((i) => i.category))].sort();
  return categories.map((c) => ({
    key: c,
    label: titleCase(c),
    items: items.filter((i) => i.category === c).sort((a, b) => a.name.localeCompare(b.name)),
  }));
}

function renderRows() {
  const entries = applyFilters(state.data.items);
  const words = terms();
  const total = state.data.items.length;

  els.summary.textContent =
    entries.length === total ? `${total} items` : `${entries.length} of ${total} items`;
  els.empty.hidden = entries.length > 0;

  // The pre-rendered flat list served the page before this script ran; from
  // here on the grouped view replaces it.
  els.rows.hidden = true;

  const groups = groupsFor(entries);
  const frag = document.createDocumentFragment();
  for (const group of groups) {
    const section = el("section", { class: "group", "aria-label": group.label ?? "Results" });
    if (group.label) {
      section.append(
        el("h2", { class: "group-head" }, [
          group.label,
          el("span", { class: "n", text: String(group.items.length) }),
        ]),
      );
    }
    section.append(
      el(
        "ol",
        { class: "rows" },
        group.items.map((item) => row(item, words)),
      ),
    );
    frag.append(section);
  }
  els.groups.replaceChildren(frag);
}

function render() {
  if (!state.data) return;
  renderToolbar();
  renderRows();
}

/* Events ---------------------------------------------------------------------------- */

function bindCatalogEvents() {
  window.addEventListener("popstate", () => {
    readQuery();
    render();
  });

  let debounce = 0;
  // Replace rather than push so typing does not fill the history.
  const applySearch = () => {
    clearTimeout(debounce);
    debounce = 0;
    navigate({ q: els.search.value.trim() }, { replace: true });
  };
  els.search.addEventListener("input", () => {
    clearTimeout(debounce);
    debounce = setTimeout(applySearch, 100);
  });
  els.search.addEventListener("keydown", (e) => {
    if (e.key === "Escape") {
      if (els.search.value) {
        els.search.value = "";
        navigate({ q: "" }, { replace: true });
      } else {
        els.search.blur();
      }
    }
    if (e.key === "ArrowDown") {
      // A keystroke still waiting on the debounce would re-render under the
      // focused row; apply it first so the arrow lands on the new results.
      if (debounce) applySearch();
      const first = els.groups.querySelector(".row-link");
      if (first) {
        e.preventDefault();
        // The document handler below would step once more from the row.
        e.stopPropagation();
        first.focus();
      }
    }
  });
  els.searchClear.addEventListener("click", () => {
    els.search.value = "";
    navigate({ q: "" });
    els.search.focus();
  });

  els.filterType.addEventListener("click", (e) => {
    const button = e.target.closest("button[data-value]");
    if (!button) return;
    navigate({ type: button.dataset.value });
  });
  els.filterCategory.addEventListener("change", () =>
    navigate({ category: els.filterCategory.value }),
  );
  els.filterPlugin.addEventListener("change", () => navigate({ plugin: els.filterPlugin.value }));
  els.sort.addEventListener("change", () => navigate({ sort: els.sort.value }));

  const reset = () => {
    navigate({ q: "", type: "", category: "", plugin: "" });
    els.search.focus();
  };
  els.clear.addEventListener("click", reset);
  els.emptyReset.addEventListener("click", reset);

  // Arrow keys walk the rows; "/" jumps to search from anywhere.
  document.addEventListener("keydown", (e) => {
    const typing = ["INPUT", "TEXTAREA", "SELECT"].includes(document.activeElement?.tagName);
    if (e.key === "/" && !typing) {
      e.preventDefault();
      els.search.focus();
      els.search.select();
      return;
    }
    if ((e.key === "ArrowDown" || e.key === "ArrowUp") && !typing) {
      const links = [...els.groups.querySelectorAll(".row-link")];
      const i = links.indexOf(document.activeElement);
      if (i === -1) return;
      e.preventDefault();
      if (e.key === "ArrowDown" && links[i + 1]) links[i + 1].focus();
      if (e.key === "ArrowUp") (links[i - 1] ?? els.search).focus();
    }
  });
}

/* Boot -------------------------------------------------------------------------------- */

async function bootCatalog() {
  if (redirectLegacyHash()) return;
  Object.assign(els, {
    search: $("search"),
    searchClear: document.querySelector(".search-clear"),
    searchKbd: document.querySelector(".search kbd"),
    filterType: $("filter-type"),
    filterCategory: $("filter-category"),
    filterPlugin: $("filter-plugin"),
    sort: $("sort"),
    clear: $("clear"),
    summary: $("summary"),
    groups: $("groups"),
    rows: $("rows"),
    empty: $("empty"),
    emptyReset: $("empty-reset"),
    loadError: $("load-error"),
  });
  readQuery();
  if (state.q) els.search.value = state.q;
  bindCatalogEvents();
  try {
    const res = await fetch(DATA_URL);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    state.data = await res.json();
  } catch {
    els.loadError.hidden = false;
    return;
  }
  render();
  document.body.dataset.ready = "";
}

initTheme();
initMenu();
initCopy();
if (document.body.dataset.page === "catalog") bootCatalog();
